import {locales,cities} from './locales.js';
import {resolveLocal,localISO,offsetText,validatePeople,checkDuration,isWorking,overlaps,ics} from './core.js';
const lang=document.documentElement.lang,T=locales[lang]||locales.ko,$=id=>document.getElementById(id);
document.title=T.title;document.querySelectorAll('[data-t]').forEach(e=>e.textContent=T[e.dataset.t]);
const names={ko:'한국어',en:'English',es:'Español',zh:'简体中文',ja:'日本語',de:'Deutsch'};for(let [code,name]of Object.entries(names)){let o=new Option(name,code);o.selected=code===lang;$('language').add(o);}
$('language').onchange=()=>location.href=new URL($('language').value==='ko'?'./':$('language').value+'/',document.baseURI);
const cityName=zone=>T.cityNames[cities.find(c=>c[0]===zone)?.[1]]||zone;
function options(select,value){for(let [zone,key]of cities){let o=new Option(T.cityNames[key]+' · '+zone,zone);o.selected=value===zone;select.add(o);}}
options($('zone'),'Asia/Seoul');
let people=[],lastText='',lastEpoch=null,lastDuration=0,id=0;
function clear(){lastText='';lastEpoch=null;$('result').replaceChildren();$('candidates').replaceChildren();$('error').textContent='';$('warning').textContent='';$('status').textContent=T.updated;$('copy').disabled=true;$('download').disabled=true;}
function label(text,id){let l=document.createElement('label');l.htmlFor=id;l.textContent=text;return l;}
function addPerson(zone='Asia/Tokyo'){if(people.length>=6)return;let pid=++id,p={zone,start:'09:00',end:'18:00'},row=document.createElement('div');row.className='person';let number=document.createElement('div');number.className='person-number';number.textContent=String(people.length+1).padStart(2,'0');let fields=document.createElement('div');fields.className='person-fields';let select=document.createElement('select');select.id='person-'+pid;options(select,zone);fields.append(label(T.city,select.id),select);let hours=document.createElement('div');hours.className='hours';for(let key of ['start','end']){let box=document.createElement('div'),input=document.createElement('input');input.type='time';input.id=key+'-'+pid;input.value=p[key];input.addEventListener('input',()=>{p[key]=input.value;clear();});box.append(label(key==='start'?T.workStart:T.workEnd,input.id),input);hours.append(box);}fields.append(hours);let remove=document.createElement('button');remove.className='remove';remove.textContent=T.remove;remove.type='button';remove.setAttribute('aria-label',T.remove+' '+cityName(zone));select.onchange=()=>{p.zone=select.value;remove.setAttribute('aria-label',T.remove+' '+cityName(p.zone));clear();};remove.onclick=()=>{people=people.filter(x=>x!==p);row.remove();numberRows();clear();};p.row=row;p.remove=remove;row.append(number,fields,remove);$('people').append(row);people.push(p);numberRows();clear();}
function numberRows(){people.forEach((p,i)=>{p.row.querySelector('.person-number').textContent=String(i+1).padStart(2,'0');p.remove.disabled=people.length===1;});$('add').disabled=people.length>=6;}
function getSettings(){let duration=checkDuration($('duration').value);validatePeople(people);return {duration,weekdays:$('weekdays').checked};}
function fail(e){$('error').textContent=T.errors[e.message]||T.errors.zone;$('status').textContent='';}
function pretty(epoch,zone){return new Intl.DateTimeFormat(lang,{timeZone:zone,weekday:'short',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(epoch);}
function render(epoch,duration,weekdays,ambiguous=false){$('result').replaceChildren();let headline=document.createElement('div');headline.className='utc';headline.textContent=localISO(epoch,'UTC')+' UTC · '+duration+' '+T.minutes;$('result').append(headline);let wrap=document.createElement('div');wrap.className='tablewrap';let table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');[T.city,T.localStart,T.localEnd,T.state].forEach(s=>{let th=document.createElement('th');th.scope='col';th.textContent=s;tr.append(th);});head.append(tr);table.append(head);let body=document.createElement('tbody');lastText=T.meeting+' · '+duration+' '+T.minutes+'\n'+localISO(epoch,'UTC')+' UTC\n';for(let p of people){let row=document.createElement('tr'),city=document.createElement('td');city.className='city-name';let name=document.createElement('strong'),zone=document.createElement('small');name.textContent=cityName(p.zone);zone.textContent=p.zone;city.append(name,zone);row.append(city);for(let time of [epoch,epoch+duration*60000]){let td=document.createElement('td'),clock=document.createElement('span'),off=document.createElement('small');clock.textContent=pretty(time,p.zone);off.textContent=offsetText(time,p.zone);td.append(clock,off);row.append(td);}let td=document.createElement('td'),working=isWorking(epoch,duration,p,weekdays);td.className=working?'good':'off';td.textContent=working?T.working:T.outside;row.append(td);body.append(row);lastText+=cityName(p.zone)+' ('+p.zone+'): '+localISO(epoch,p.zone)+' '+offsetText(epoch,p.zone)+' → '+localISO(epoch+duration*60000,p.zone)+' '+offsetText(epoch+duration*60000,p.zone)+' · '+(working?T.working:T.outside)+'\n';}table.append(body);wrap.append(table);$('result').append(wrap);lastEpoch=epoch;lastDuration=duration;$('copy').disabled=false;$('download').disabled=false;$('warning').textContent=ambiguous?T.ambiguous:'';$('status').textContent='';}
$('calculate').onclick=()=>{clear();try{let s=getSettings(),values=resolveLocal($('date').value,$('time').value,$('zone').value);if(!values.length)throw Error('missing');let index=$('occurrence').value==='later'?values.length-1:0;render(values[index],s.duration,s.weekdays,values.length>1);}catch(e){fail(e);}};
$('overlap').onclick=async()=>{clear();$('status').textContent=T.searching;$('overlap').disabled=true;await new Promise(requestAnimationFrame);try{let s=getSettings(),values=overlaps($('date').value,$('zone').value,s.duration,people,s.weekdays);$('status').textContent=values.length?T.found+': '+values.length:T.empty;if(values.length){let h=document.createElement('h3');h.textContent=T.found;$('candidates').append(h);for(let epoch of values){let button=document.createElement('button');button.className='candidate';button.textContent=localISO(epoch,$('zone').value)+' · '+offsetText(epoch,$('zone').value);button.setAttribute('aria-label',T.select+' '+button.textContent);button.onclick=()=>{let v=localISO(epoch,$('zone').value);$('date').value=v.slice(0,10);$('time').value=v.slice(11);let choices=resolveLocal($('date').value,$('time').value,$('zone').value);$('occurrence').value=choices.indexOf(epoch)>0?'later':'earlier';render(epoch,s.duration,s.weekdays,choices.length>1);};$('candidates').append(button);}}}catch(e){fail(e);}finally{$('overlap').disabled=false;}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(lastText);$('status').textContent=T.copied;}catch{$('status').textContent=T.copyFail;}};
$('download').onclick=()=>{if(lastEpoch===null)return;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([ics(lastEpoch,lastDuration,T.meeting)],{type:'text/calendar;charset=utf-8'}));a.download='world-meeting.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('add').onclick=()=>addPerson();
document.querySelectorAll('#reference input,#reference select,#weekdays').forEach(e=>e.addEventListener('input',clear));
function sample(){people=[];$('people').replaceChildren();addPerson('Asia/Seoul');addPerson('Europe/London');addPerson('America/New_York');$('zone').value='Asia/Seoul';$('date').value='2026-10-26';$('time').value='17:00';$('duration').value='60';$('occurrence').value='earlier';$('weekdays').checked=true;$('calculate').click();}
$('sample').onclick=sample;sample();
